<script>
  (function() {
    const searchInput = document.getElementById('searchInput');
    const clearSearchBtn = document.getElementById('clearSearchBtn');
    const categoryChips = document.querySelectorAll('.category-chip');
    const statusTabs = document.querySelectorAll('.status-tab');
    const dragonCards = document.querySelectorAll('.dragon-card');
    const resultCount = document.getElementById('resultCount');
    const emptyState = document.getElementById('emptyState');
    const resetAllFilterBtn = document.getElementById('resetAllFilterBtn');

    let activeCategory = 'all';
    let activeStatus = 'all';
    let searchQuery = '';

    function filterDragons() {
      let visibleCount = 0;

      dragonCards.forEach(card => {
        const name = (card.getAttribute('data-name') || '').toLowerCase();
        const code = (card.getAttribute('data-code') || '').toLowerCase();
        const category = card.getAttribute('data-category') || '';
        const status = card.getAttribute('data-status') || '';

        const matchesSearch = !searchQuery || name.includes(searchQuery) || code.includes(searchQuery);
        const matchesCategory = (activeCategory === 'all') || (category === activeCategory);
        const matchesStatus = (activeStatus === 'all') || (status === activeStatus);

        if (matchesSearch && matchesCategory && matchesStatus) {
          card.classList.remove('hidden');
          visibleCount++;
        } else {
          card.classList.add('hidden');
        }
      });

      if (visibleCount === 0) {
        emptyState.classList.remove('hidden');
        emptyState.classList.add('flex');
      } else {
        emptyState.classList.add('hidden');
        emptyState.classList.remove('flex');
      }

      resultCount.textContent = `Menampilkan ${visibleCount} unit terdaftar`;
    }

    // Pencarian
    searchInput.addEventListener('input', (e) => {
      searchQuery = e.target.value.trim().toLowerCase();
      if (searchQuery.length > 0) {
        clearSearchBtn.classList.remove('hidden');
      } else {
        clearSearchBtn.classList.add('hidden');
      }
      filterDragons();
    });

    clearSearchBtn.addEventListener('click', () => {
      searchInput.value = '';
      searchQuery = '';
      clearSearchBtn.classList.add('hidden');
      searchInput.focus();
      filterDragons();
    });

    // Kategori Filter Chips
    categoryChips.forEach(chip => {
      chip.addEventListener('click', () => {
        categoryChips.forEach(c => {
          c.classList.remove('bg-primary-container', 'text-gold-ink', 'font-semibold', 'border-primary-container');
          c.classList.add('bg-surface', 'text-text-muted', 'border-border');
        });

        chip.classList.remove('bg-surface', 'text-text-muted', 'border-border');
        chip.classList.add('bg-primary-container', 'text-gold-ink', 'font-semibold', 'border-primary-container');

        activeCategory = chip.getAttribute('data-category');
        filterDragons();
      });
    });

    // Status Filter Tabs
    statusTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        statusTabs.forEach(t => {
          t.classList.remove('text-primary-container', 'bg-surface-raised', 'font-medium');
          t.classList.add('text-text-muted');
        });

        tab.classList.remove('text-text-muted');
        tab.classList.add('text-primary-container', 'bg-surface-raised', 'font-medium');

        activeStatus = tab.getAttribute('data-status');
        filterDragons();
      });
    });

    // Reset All Filter
    if (resetAllFilterBtn) {
      resetAllFilterBtn.addEventListener('click', () => {
        searchInput.value = '';
        searchQuery = '';
        clearSearchBtn.classList.add('hidden');

        activeCategory = 'all';
        categoryChips.forEach(c => {
          if (c.getAttribute('data-category') === 'all') {
            c.classList.remove('bg-surface', 'text-text-muted', 'border-border');
            c.classList.add('bg-primary-container', 'text-gold-ink', 'font-semibold', 'border-primary-container');
          } else {
            c.classList.remove('bg-primary-container', 'text-gold-ink', 'font-semibold', 'border-primary-container');
            c.classList.add('bg-surface', 'text-text-muted', 'border-border');
          }
        });

        activeStatus = 'all';
        statusTabs.forEach(t => {
          if (t.getAttribute('data-status') === 'all') {
            t.classList.add('text-primary-container', 'bg-surface-raised', 'font-medium');
            t.classList.remove('text-text-muted');
          } else {
            t.classList.remove('text-primary-container', 'bg-surface-raised', 'font-medium');
            t.classList.add('text-text-muted');
          }
        });

        filterDragons();
      });
    }

    // Modal Peminjaman Interaktif
    const rentalModal = document.getElementById('rentalModal');
    const closeModalBtn = document.getElementById('closeModalBtn');
    const cancelModalBtn = document.getElementById('cancelModalBtn');
    const rentalForm = document.getElementById('rentalForm');
    const modalDragonCode = document.getElementById('modalDragonCode');
    const modalDragonName = document.getElementById('modalDragonName');
    const modalDragonCategory = document.getElementById('modalDragonCategory');
    const durationBtns = document.querySelectorAll('.duration-btn');
    const selectedDaysInput = document.getElementById('selectedDaysInput');
    const endDateDisplay = document.getElementById('endDateDisplay');
    const toast = document.getElementById('toastNotification');
    const toastMessage = document.getElementById('toastMessage');

    const rentActionBtns = document.querySelectorAll('.rent-action-btn');

    function updateEndDate(days) {
      const baseDate = 24; // Mock 24 Okt 2026
      const end = baseDate + parseInt(days, 10);
      endDateDisplay.textContent = `${end} Okt 2026`;
    }

    rentActionBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const code = btn.getAttribute('data-code');
        const name = btn.getAttribute('data-name');
        const category = btn.getAttribute('data-category');

        modalDragonCode.textContent = `Kode: ${code}`;
        modalDragonName.textContent = name;
        modalDragonCategory.textContent = `${category} • Registri Tersertifikasi`;

        rentalModal.classList.remove('hidden');
      });
    });

    function closeModal() {
      rentalModal.classList.add('hidden');
    }

    if (closeModalBtn) closeModalBtn.addEventListener('click', closeModal);
    if (cancelModalBtn) cancelModalBtn.addEventListener('click', closeModal);

    rentalModal.addEventListener('click', (e) => {
      if (e.target === rentalModal) {
        closeModal();
      }
    });

    durationBtns.forEach(dBtn => {
      dBtn.addEventListener('click', () => {
        durationBtns.forEach(b => {
          b.classList.remove('bg-primary-container', 'border-primary-container', 'text-gold-ink', 'font-semibold');
          b.classList.add('bg-surface', 'border-border', 'text-text-primary');
        });

        dBtn.classList.remove('bg-surface', 'border-border', 'text-text-primary');
        dBtn.classList.add('bg-primary-container', 'border-primary-container', 'text-gold-ink', 'font-semibold');

        const days = dBtn.getAttribute('data-days');
        selectedDaysInput.value = days;
        updateEndDate(days);
      });
    });

    // Form Submission Feedback
    rentalForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const dragonName = modalDragonName.textContent;
      closeModal();

      // Show Toast Notification
      toastMessage.textContent = `${dragonName} berhasil terdaftar dipinjam.`;
      toast.classList.remove('translate-y-24', 'opacity-0');
      toast.classList.add('translate-y-0', 'opacity-100');

      setTimeout(() => {
        toast.classList.remove('translate-y-0', 'opacity-100');
        toast.classList.add('translate-y-24', 'opacity-0');
      }, 4000);
    });

    // Delegasi klik Tombol Detail (informational)
    const detailBtns = document.querySelectorAll('.view-detail-btn');
    detailBtns.forEach(b => {
      b.addEventListener('click', () => {
        const code = b.getAttribute('data-code');
        // Quick visual ping on card
        const card = b.closest('.dragon-card');
        card.classList.add('ring-1', 'ring-primary-container');
        setTimeout(() => card.classList.remove('ring-1', 'ring-primary-container'), 600);
      });
    });

  })();
</script></main><footer class="w-full bg-surface-muted border-t border-border mt-auto"><div class="max-w-7xl mx-auto px-margin md:px-margin-tablet lg:px-margin-desktop py-space-lg flex flex-col sm:flex-row items-center justify-between gap-space-md font-helper-text text-helper-text text-text-subtle"><div class="flex items-center gap-space-sm"><span class="font-section-title text-card-title text-primary leading-none">᚛ᚇ᚜</span><span>DracoRent Guild Ledger — Registri Resmi Serikat Penjaga Naga</span></div><div class="flex items-center gap-space-lg"><span class="font-code-metadata text-code-metadata text-text-subtle">ARSIP RESMI SERIKAT • ERA KEEMASAN KE-IV</span></div></div></footer><script>
(function() {
  const pathMap = {
    'masuk': 'masuk.html',
    'masuk-kurator': 'masuk.html',
    'keluar': 'masuk.html',
    'ringkasan': 'ringkasan.html',
    'unit-naga': 'unit-naga.html',
    'tambah-unit-modal': 'tambah-unit-modal.html',
    'kategori': 'kategori.html',
    'anggota': 'anggota.html',
    'pinjaman-aktif': 'pinjaman-aktif.html',
    'riwayat-dan-laporan': 'riwayat-dan-laporan.html',
    'katalog-naga': 'katalog-naga.html',
    'katalog-publik': 'katalog-naga.html',
    'detail-naga': 'detail-naga.html',
    'pinjaman-saya': 'pinjaman-saya.html',
    'riwayat-rental': 'riwayat-rental.html',
    'profil-saya': 'profil-saya.html'
  };

  function navigateTo(slug) {
    const target = pathMap[slug] || (slug + '.html');
    if (window.parent && window.parent !== window && window.parent.switchDracoScreen) {
      window.parent.switchDracoScreen(slug);
      return;
    }
    const inScreensDir = window.location.pathname.replace(/\\/g, '/').includes('/screens/');
    window.location.href = inScreensDir ? target : ('screens/' + target);
  }

  document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('[data-path]').forEach(function(el) {
      el.addEventListener('click', function(e) {
        const p = el.getAttribute('data-path');
        if (p && pathMap[p]) {
          e.preventDefault();
          navigateTo(p);
        }
      });
    });

    // Wire catalog detail & rent buttons to detail-naga screen
    document.querySelectorAll('.view-detail-btn, .rent-action-btn').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        navigateTo('detail-naga');
      });
    });

    // Wire breadcrumb back to catalog
    document.querySelectorAll('a').forEach(function(a) {
      const txt = (a.textContent || '').trim();
      if (txt.includes('Kembali ke Katalog')) {
        a.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('katalog-naga');
        });
      }
      if (txt.includes('Lihat Semua Kontrak')) {
        a.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('pinjaman-aktif');
        });
      }
    });

    // Wire Proses Pengembalian buttons on dashboard
    document.querySelectorAll('button').forEach(function(btn) {
      const txt = (btn.textContent || '').trim();
      if (txt.includes('Proses Pengembalian')) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('pinjaman-aktif');
        });
      }
      if (txt.includes('+ Tambah Unit Baru') || txt.includes('Tambah Unit Naga')) {
        btn.addEventListener('click', function(e) {
          if (!document.getElementById('modal-backdrop') && !window.location.pathname.includes('tambah-unit-modal')) {
            e.preventDefault();
            navigateTo('tambah-unit-modal');
          }
        });
      }
      if (txt.includes('Kelola Kategori')) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('kategori');
        });
      }
      if (txt.includes('+ Tambah Anggota Serikat') && !document.getElementById('panel-tambah-anggota')) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('anggota');
        });
      }
      if (txt.includes('Semua Pinjaman Aktif')) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('pinjaman-aktif');
        });
      }
    });

    // Wire login form submit
    const loginForm = document.getElementById('loginForm');
    if (loginForm) {
      loginForm.addEventListener('submit', function(e) {
        e.preventDefault();
        const emailVal = (document.getElementById('email')?.value || '').toLowerCase();
        if (emailVal.includes('admin') || emailVal.includes('kaelen') || emailVal.includes('kurator')) {
          navigateTo('ringkasan');
        } else {
          navigateTo('katalog-naga');
        }
      });
    }
  });
})();
</script>
<script src="/js/dracorent-app.js"></script></body></html>


